using FluentAssertions;

[Fact]
public void Order_Should_Have_Valid_Total()
{
    var order = new Order
    {
        Items = new List<OrderItem>
        {
            new() { Price = 10, Quantity = 2 },
            new() { Price = 5, Quantity = 1 }
        }
    };

    order.Total.Should().Be(25);
    order.Items.Should().HaveCount(2);
    order.Items[0].Price.Should().BeGreaterThan(0);
}

[Fact]
public void Users_Should_Contain_Admin()
{
    var users = new[]
    {
        new User { Name = "Alice", Role = "User" },
        new User { Name = "Bob", Role = "Admin" }
    };

    users.Should().Contain(u => u.Role == "Admin");
    users.Should().OnlyHaveUniqueItems();
    users.Select(u => u.Name).Should().BeInAscendingOrder();
}
